#[async_trait::async_trait]
impl carbon_core::clickhouse::BatchCommit for HeavenInstructionRow {
    async fn batch_commit(
        &self,
        client: &clickhouse::Client,
        rows: &[Self],
    ) -> carbon_core::error::CarbonResult<()> {
        macro_rules! commit_branch {
            ($variant:ident, $row:ty) => {
                if let Self::$variant(source) = self {
                    let branch_rows: Vec<$row> = rows
                        .iter()
                        .filter_map(|row| match row {
                            Self::$variant(row) => Some(row.clone()),
                            _ => None,
                        })
                        .collect();
                    return <$row as carbon_core::clickhouse::Insert>::insert(
                        source,
                        client,
                        &branch_rows,
                    )
                    .await;
                }
            };
        }

        commit_branch!(AddLiquidityProPool, AddLiquidityProPoolRow);
        commit_branch!(AdminBorrowSol, AdminBorrowSolRow);
        commit_branch!(AdminClaimMsol, AdminClaimMsolRow);
        commit_branch!(
            AdminClaimProCreatorTradingFees,
            AdminClaimProCreatorTradingFeesRow
        );
        commit_branch!(AdminClaimStakingRewards, AdminClaimStakingRewardsRow);
        commit_branch!(
            AdminClaimStandardCreatorTradingFees,
            AdminClaimStandardCreatorTradingFeesRow
        );
        commit_branch!(AdminDepositMsol, AdminDepositMsolRow);
        commit_branch!(AdminMintMsol, AdminMintMsolRow);
        commit_branch!(AdminRepaySol, AdminRepaySolRow);
        commit_branch!(AdminSetTransferFee, AdminSetTransferFeeRow);
        commit_branch!(AdminUnstakeMsol, AdminUnstakeMsolRow);
        commit_branch!(
            AdminUpdateProLiquidityPoolState,
            AdminUpdateProLiquidityPoolStateRow
        );
        commit_branch!(
            AdminUpdateStandardLiquidityPoolState,
            AdminUpdateStandardLiquidityPoolStateRow
        );
        commit_branch!(AdminWithdrawMsol, AdminWithdrawMsolRow);
        commit_branch!(AdminWithdrawTransferFee, AdminWithdrawTransferFeeRow);
        commit_branch!(Buy, BuyRow);
        commit_branch!(
            ClaimProCreatorTradingFeeProtocolFees,
            ClaimProCreatorTradingFeeProtocolFeesRow
        );
        commit_branch!(ClaimProCreatorTradingFees, ClaimProCreatorTradingFeesRow);
        commit_branch!(
            ClaimProLiquidityProviderTradingFees,
            ClaimProLiquidityProviderTradingFeesRow
        );
        commit_branch!(ClaimProProtocolTradingFees, ClaimProProtocolTradingFeesRow);
        commit_branch!(
            ClaimProReflectionTradingFees,
            ClaimProReflectionTradingFeesRow
        );
        commit_branch!(
            ClaimStandardCreatorTradingFeeProtocolFees,
            ClaimStandardCreatorTradingFeeProtocolFeesRow
        );
        commit_branch!(
            ClaimStandardCreatorTradingFees,
            ClaimStandardCreatorTradingFeesRow
        );
        commit_branch!(
            ClaimStandardProtocolTradingFees,
            ClaimStandardProtocolTradingFeesRow
        );
        commit_branch!(
            ClaimStandardReflectionTradingFees,
            ClaimStandardReflectionTradingFeesRow
        );
        commit_branch!(CloseProtocolLookupTable, CloseProtocolLookupTableRow);
        commit_branch!(
            CreateOrUpdateProtocolFeeAdmin,
            CreateOrUpdateProtocolFeeAdminRow
        );
        commit_branch!(CreateOrUpdateProtocolOwner, CreateOrUpdateProtocolOwnerRow);
        commit_branch!(
            CreateOrUpdateProtocolStakingAdmin,
            CreateOrUpdateProtocolStakingAdminRow
        );
        commit_branch!(CreateProLiquidityPool, CreateProLiquidityPoolRow);
        commit_branch!(CreateProtocolConfig, CreateProtocolConfigRow);
        commit_branch!(CreateProtocolLookupTable, CreateProtocolLookupTableRow);
        commit_branch!(CreateStandardLiquidityPool, CreateStandardLiquidityPoolRow);
        commit_branch!(
            CreatorSetProMarketCapCreatorFee,
            CreatorSetProMarketCapCreatorFeeRow
        );
        commit_branch!(CreatorSetProMarketCapLpFee, CreatorSetProMarketCapLpFeeRow);
        commit_branch!(
            CreatorSetProMarketCapReflectionFee,
            CreatorSetProMarketCapReflectionFeeRow
        );
        commit_branch!(CreatorSetProSlotCreatorFee, CreatorSetProSlotCreatorFeeRow);
        commit_branch!(CreatorToggleProDeposit, CreatorToggleProDepositRow);
        commit_branch!(CreatorToggleProSwap, CreatorToggleProSwapRow);
        commit_branch!(CreatorToggleProWithdraw, CreatorToggleProWithdrawRow);
        commit_branch!(
            DeactivateProtocolLookupTable,
            DeactivateProtocolLookupTableRow
        );
        commit_branch!(ExtendProtocolLookupTable, ExtendProtocolLookupTableRow);
        commit_branch!(InitializeProtocolLending, InitializeProtocolLendingRow);
        commit_branch!(ProBuy, ProBuyRow);
        commit_branch!(ProSell, ProSellRow);
        commit_branch!(RemainingAccountsStub, RemainingAccountsStubRow);
        commit_branch!(RemoveLiquidityProPool, RemoveLiquidityProPoolRow);
        commit_branch!(Sell, SellRow);
        commit_branch!(SetProtocolSlotFees, SetProtocolSlotFeesRow);
        commit_branch!(TransferLpTokens, TransferLpTokensRow);
        commit_branch!(UpdateAllowCreatePool, UpdateAllowCreatePoolRow);
        commit_branch!(
            UpdateCreatorTradingFeeReceiver,
            UpdateCreatorTradingFeeReceiverRow
        );
        commit_branch!(
            UpdateProCreatorTradingFeeReceiver,
            UpdateProCreatorTradingFeeReceiverRow
        );
        commit_branch!(UpdateProtocolConfig, UpdateProtocolConfigRow);
        commit_branch!(CpiEvent, CpiEventRow);
        Ok(())
    }
}
